        level.m_8767_((ParticleOptions)ParticleTypes.f_123812_, at.f_82479_, at.f_82480_ + 1.0, at.f_82481_, 2, 1.5, 0.5, 1.5, 0.0);
        level.m_8767_((ParticleOptions)ParticleTypes.f_123744_, at.f_82479_, at.f_82480_ + 0.5, at.f_82481_, 260, 2.5, 0.8, 2.5, 0.45);
