        level.m_8767_((ParticleOptions)ParticleTypes.f_123755_, at.f_82479_, at.f_82480_ + 1.0, at.f_82481_, 80, 4.0, 1.0, 4.0, 0.08);
        CameraShakeManager.addCameraShake((CameraShakeData)new CameraShakeData((Level)level, 30, at, 40.0f));
    }

    public static void reborn(ServerLevel level, Vec3 at) {
        GsFx.play(level, at, "minecraft:item.totem.use", SoundEvents.f_12513_, 3.0f, 0.65f);
        GsFx.play(level, at, "minecraft:entity.ender_dragon.growl", SoundEvents.f_11894_, 3.0f, 1.4f);
