import net.minecraft.world.entity.Entity;
import net.minecraft.world.level.Level;
import net.minecraft.world.phys.Vec3;

public final class ReckoningFx {
    private ReckoningFx() {
    }

    public static void begins(ServerLevel level, Vec3 at) {
        GsFx.play(level, at, "minecraft:block.beacon.activate", SoundEvents.f_11736_, 1.8f, 1.5f);
        GsFx.play(level, at, "minecraft:block.amethyst_block.resonate", SoundEvents.f_276532_, 1.6f, 1.4f);
        GsFx.play(level, at, "minecraft:entity.illusioner.prepare_mirror", SoundEvents.f_12054_, 1.2f, 1.2f);
    }

    public static void gathering(ServerLevel level, Vec3 at, float fill, int tick) {
        Vec3 hands = at.m_82520_(0.0, 1.35, 0.0);
        if (tick % 4 == 0) {
            GsFx.play(level, hands, "minecraft:block.note_block.bell", (SoundEvent)SoundEvents.f_12210_.m_203334_(), 0.8f, 0.6f + fill * 1.3f);
        }
        if (tick % 8 == 0) {
            GsFx.play(level, hands, "minecraft:block.conduit.ambient", SoundEvents.f_11768_, 0.9f, 0.7f + fill * 0.8f);
        }
        if (tick % 20 == 0) {
            GsFx.play(level, hands, "minecraft:block.beacon.power_select", SoundEvents.f_11739_, 1.1f, 0.6f + fill * 1.2f);
        }
        if (tick % 3 != 0) {
            return;
        }
        int count = 2 + Mth.m_14143_((float)(fill * 6.0f));
        for (int i = 0; i < count; ++i) {
            double a = level.f_46441_.m_188500_() * Math.PI * 2.0;
            double rr = 2.0 + level.f_46441_.m_188500_() * (2.5 + (double)fill * 4.0);
            double x = hands.f_82479_ + Math.cos(a) * rr;
            double y = hands.f_82480_ + (level.f_46441_.m_188500_() - 0.5) * 2.5;
            double z = hands.f_82481_ + Math.sin(a) * rr;
            Vec3 toward = new Vec3(hands.f_82479_ - x, hands.f_82480_ - y, hands.f_82481_ - z).m_82541_().m_82490_(0.2 + (double)fill * 0.55);
            level.m_8767_((ParticleOptions)ParticleTypes.f_123810_, x, y, z, 0, toward.f_82479_, toward.f_82480_, toward.f_82481_, 1.0);
        }
        if (fill > 0.72f && tick % 6 == 0) {
            level.m_8767_((ParticleOptions)ParticleTypes.f_175830_, hands.f_82479_, hands.f_82480_, hands.f_82481_, 4, 0.25, 0.25, 0.25, 0.03);
        }
    }

    public static void lost(ServerLevel level, Vec3 at) {
        Vec3 hands = at.m_82520_(0.0, 1.35, 0.0);
        GsFx.play(level, hands, "minecraft:block.beacon.deactivate", SoundEvents.f_11738_, 1.6f, 1.3f);
        GsFx.play(level, hands, "minecraft:block.fire.extinguish", SoundEvents.f_11937_, 1.2f, 0.7f);
        level.m_8767_((ParticleOptions)ParticleTypes.f_123762_, hands.f_82479_, hands.f_82480_, hands.f_82481_, 14, 0.2, 0.2, 0.2, 0.01);
    }

    public static void released(ServerLevel level, Vec3 target) {
        GsFx.play(level, target, "minecraft:item.totem.use", SoundEvents.f_12513_, 3.0f, 0.75f);
        GsFx.play(level, target, "minecraft:entity.evoker.cast_spell", SoundEvents.f_11862_, 2.4f, 0.6f);
        GsFx.play(level, target, "minecraft:block.beacon.power_select", SoundEvents.f_11739_, 2.0f, 2.0f);
    }

    public static void lands(ServerLevel level, Vec3 at, double radius) {
        GsFx.play(level, at, "minecraft:entity.lightning_bolt.thunder", SoundEvents.f_12090_, 8.0f, 0.6f);
        GsFx.play(level, at, "minecraft:entity.warden.sonic_boom", SoundEvents.f_215771_, 6.0f, 0.55f);
        GsFx.play(level, at, "minecraft:entity.generic.explode", SoundEvents.f_11913_, 7.0f, 0.5f);
        GsFx.play(level, at, "minecraft:block.conduit.activate", SoundEvents.f_11767_, 5.0f, 0.9f);
        GsFx.play(level, at, "minecraft:item.trident.thunder", SoundEvents.f_12521_, 4.0f, 1.1f);
        GsFx.play(level, at, "minecraft:block.note_block.chime", (SoundEvent)SoundEvents.f_12211_.m_203334_(), 3.0f, 2.0f);
        level.m_8767_((ParticleOptions)ParticleTypes.f_123747_, at.f_82479_, at.f_82480_ + 2.0, at.f_82481_, 8, 0.6, 1.5, 0.6, 0.0);
        level.m_8767_((ParticleOptions)ParticleTypes.f_235902_, at.f_82479_, at.f_82480_ + 1.5, at.f_82481_, 1, 0.0, 0.0, 0.0, 0.0);
        ReckoningFx.ring(level, at, radius * 0.9, 0.9);
        CameraShakeManager.addCameraShake((CameraShakeData)new CameraShakeData((Level)level, 50, at, (float)(radius * 7.0)));
    }

    public static void standing(ServerLevel level, Vec3 at, double radius, float progress) {
        GsFx.play(level, at, "minecraft:block.beacon.ambient", SoundEvents.f_11737_, 2.6f, 1.5f - progress * 0.35f);
        GsFx.play(level, at, "minecraft:block.amethyst_block.chime", SoundEvents.f_144243_, 1.6f, 1.6f - progress * 0.4f);
        ReckoningFx.ring(level, at, radius * (1.0 + (double)progress * 2.2), 0.05);
    }

    public static void closes(ServerLevel level, Vec3 at, double radius) {
        GsFx.play(level, at, "minecraft:block.beacon.deactivate", SoundEvents.f_11738_, 2.6f, 1.2f);
        GsFx.play(level, at, "minecraft:block.conduit.deactivate", SoundEvents.f_11824_, 2.0f, 1.0f);
    }

    public static void judged(ServerLevel level, Entity target) {
        Vec3 at = target.m_20191_().m_82399_();
        level.m_8767_((ParticleOptions)ParticleTypes.f_123810_, at.f_82479_, at.f_82480_, at.f_82481_, 30, 0.35, 0.6, 0.35, 0.5);
        level.m_8767_((ParticleOptions)ParticleTypes.f_123747_, at.f_82479_, at.f_82480_, at.f_82481_, 1, 0.0, 0.0, 0.0, 0.0);

